svg.icone-svg {
  display: inline-flex;
}
svg.icone-svg.svg-small {
  --size-icon-svg: var(--icone-s);
}
svg.icone-svg.svg-medium {
  --size-icon-svg: var(--icone-m);
}
svg.icone-svg.svg-large {
  --size-icon-svg: var(--icone-l);
}
svg.icone-svg.svg-xlarge {
  --size-icon-svg: var(--taille-5xl);
}
svg.icone-svg {
  --scale-ratio-badgesvg: 0.45;
  --ecart-badgesvg: 0.3rem;
  width: var(--size-icon-svg);
  height: var(--size-icon-svg);
  overflow: visible;
}
svg.icone-svg.icone-badge {
  pointer-events: none;
  --fill-badgesvg: currentColor;
  --ecart-moins-badgesvg: calc(var(--ecart-badgesvg) * -1);
  transform: translate(var(--translateX-badgesvg), var(--translateY-badgesvg)) scale(var(--scale-ratio-badgesvg));
}
svg.icone-svg.icone-badge path {
  fill: var(--fill-badgesvg);
  stroke: var(--stroke-color);
  stroke-width: 3px;
  paint-order: stroke fill;
}
svg.icone-svg.icone-badge.large-path path {
  stroke-width: 7px;
}
svg.icone-svg.icone-badge, svg.icone-svg.icone-badge.badge-tr {
  transform-origin: top right;
  --translateX-badgesvg: var(--ecart-badgesvg);
  --translateY-badgesvg: var(--ecart-moins-badgesvg);
}
svg.icone-svg.icone-badge.small, svg.icone-svg.icone-badge.badge-tr.small {
  --scale-ratio-badgesvg: 0.4;
  --ecart-badgesvg: 0.001rem;
}
svg.icone-svg.icone-badge.badge-br {
  transform-origin: bottom right;
  --translateY-badgesvg: var(--ecart-badgesvg);
}
svg.icone-svg.icone-badge.badge-bl {
  transform-origin: bottom left;
  --translateX-badgesvg: var(--ecart-moins-badgesvg);
  --translateY-badgesvg: var(--ecart-badgesvg);
}
svg.icone-svg.icone-badge.badge-tl {
  transform-origin: top left;
  --translateX-badgesvg: var(--ecart-moins-badgesvg);
}
svg.icone-svg.icone-badge.badge-cr {
  transform-origin: center right;
  --translateX-badgesvg: var(--ecart-badgesvg);
  --translateY-badgesvg: 0;
}
svg.icone-svg.icone-badge.badge-cc {
  transform-origin: center;
  --translateX-badgesvg: 0;
  --translateY-badgesvg: 0;
}
svg.icone-svg.icone-badge.badge-cl {
  transform-origin: left center;
  --translateX-badgesvg: var(--ecart-moins-badgesvg);
  --translateY-badgesvg: 0;
}
svg.icone-svg.icone-badge {
}
