.toast {
  visibility: hidden;
  position: fixed;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  z-index: 10005;
  padding: 0.8rem 1.2rem;
  border-radius: 0.7rem;
  font-size: var(--taille-l);
  font-weight: 600;
  box-shadow: 0.3rem 0.3rem 0.6rem 0.6rem rgba(var(--color-shadow-rgb), 0.05);
}
.toast .icone-svg {
  flex: none;
}
.toast p {
  margin-right: 0.8rem;
  flex: 1 1 auto;
}
.toast .btn {
  cursor: pointer;
  flex: none;
  width: 2rem;
}
.toast.shown {
  visibility: visible;
  bottom: 1.6rem;
  max-width: 50rem;
  min-height: 40px;
  animation: intro-bottom 0.3s, open-toast 0.3s 0.25s;
}
.toast.shown.top {
  bottom: calc(100% - 6rem);
  top: 1.6rem;
  animation: intro-top 0.3s, open-toast 0.3s 0.25s;
}
.toast, .toast.top {
  left: 50%;
  transform: translateX(-50%);
}
.toast.to-right {
  left: unset;
  right: 1.6rem;
  transform: translateX(0);
  margin-right: 1.6rem;
}

.EspaceMobileIndex .toast {
  top: calc(100% - 9rem);
  max-width: calc(100% - 0.8rem);
  font-size: 1.1rem;
  line-height: 1.1;
}

@keyframes intro-bottom {
  from {
    bottom: -50px;
    opacity: 0;
    max-width: 4rem;
    max-height: 50px;
    overflow: hidden;
  }
  to {
    bottom: 1.6rem;
    opacity: 0.99;
    max-width: 4rem;
    max-height: 50px;
    overflow: hidden;
  }
}
@keyframes intro-top {
  from {
    top: -50px;
    opacity: 0;
    max-width: 4rem;
    max-height: 50px;
    overflow: hidden;
    white-space: nowrap;
  }
  to {
    top: 1.6rem;
    opacity: 0.99;
    max-width: 4rem;
    max-height: 50px;
    overflow: hidden;
    white-space: nowrap;
  }
}
@keyframes open-toast {
  0% {
    max-width: 4rem;
    max-height: 50px;
    overflow: hidden;
    white-space: nowrap;
  }
  95% {
    max-height: 50px;
    overflow: hidden;
    white-space: nowrap;
  }
  100% {
    max-width: 50rem;
    max-height: none;
    overflow: visible;
    white-space: normal;
  }
}
